+#!/usr/bin/env python3
+"""W17 Coder-4: 4APP baseline/final runner — install + run + frontier census.
+Reusable: python3 w17_4app_run.py <tag>  (tag: baseline|final)"""
+import json, subprocess, re, sys, shutil, hashlib
+from pathlib import Path
+
+BASE = Path('/home/z/my-project')
+BIN = BASE / 'miniandroid/build/miniandroid'
+OUT = BASE / 'evidence/w17'
+TAG = sys.argv[1] if len(sys.argv) > 1 else 'baseline'
+SECS = 40
+
+APPS = [
+    ('net.thunderbird.android', BASE / 'upload/net.thunderbird.android_33.apk'),
+    ('com.keylesspalace.tusky', BASE / 'upload/com.keylesspalace.tusky_145.apk'),
+    ('com.nextcloud.client', BASE / 'upload/com.nextcloud.client_350000290.apk'),
+    ('org.connectbot', BASE / 'upload/org.connectbot_11101000.apk'),
+]
+
+def run():
+    results = {}
+    for pkg, apk in APPS:
+        print('==', pkg, flush=True)
+        store = OUT / f'store_{pkg}'
+        store.mkdir(parents=True, exist_ok=True)
+        if not (store / 'data').exists():
+            subprocess.run([str(BIN), 'install', str(apk), '--data-root', str(store)],
+                           capture_output=True, timeout=600)
+        apps = store / 'data' / 'app'
+        dpkg = None
+        if apps.exists():
+            ds = [d.name for d in sorted(apps.iterdir())
+                  if d.is_dir() and not d.name.startswith('.')
+                  and (d / 'base.apk').exists()]
+            dpkg = ds[0] if ds else None
+        if not dpkg:
+            results[pkg] = dict(status='INSTALL_FAIL'); continue
+        rundir = OUT / f'run_{TAG}_{pkg}'
+        shutil.rmtree(rundir, ignore_errors=True)
+        console = OUT / f'{TAG}_{pkg}.console.log'
+        cmd = [str(BIN), 'run', '--execution-mode', 'real-dalvik',
+               '--data-root', str(store), '-o', str(rundir),
+               '--package', dpkg, '--seconds', str(SECS), '--trace']
+        with open(console, 'wb') as cf:
+            try:
+                subprocess.run(cmd, stdout=cf, stderr=subprocess.STDOUT,
+                               cwd=str(BASE), timeout=SECS + 240)
+            except subprocess.TimeoutExpired:
+                pass
+        log = console.read_text(errors='ignore')
+        uncaught = re.findall(r'FATAL|Uncaught', log)
+        # frontier: last exception + last law markers
+        excs = re.findall(r'(\w+(?:Exception|Error)[^:\n]*(?::[^\n]*)?)', log)
+        shot = None
+        for cand in ([rundir / 'final_frame.png'] +
+                     sorted(rundir.glob('**/*.png'), reverse=True)):
+            if cand.exists():
+                shot = cand; break
+        shot_sha = ''
+        if shot:
+            shot_sha = hashlib.sha256(shot.read_bytes()).hexdigest()[:16]
+        results[pkg] = dict(
+            status='OK', dpkg=dpkg, uncaught=len(uncaught),
+            last_exc=(excs[-6:] if excs else []),
+            screenshot=str(shot) if shot else None, shot_sha16=shot_sha,
+            log_lines=len(log.splitlines()))
+        # print compact frontier
+        print('   uncaught=%d shot=%s' % (len(uncaught), shot_sha or 'NONE'))
+        for e in (excs[-6:] if excs else []):
+            print('   EXC:', e[:150])
+    (OUT / f'{TAG}_4app.json').write_text(json.dumps(results, indent=1))
+    print('saved', OUT / f'{TAG}_4app.json')
+
+if __name__ == '__main__':
+    run()
